import sys

def main():
    # Read X from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    X = int(input_data[0])

    # Calculate the sum of all numbers in the 9x9 grid excluding X
    total_sum = 0
    for i in range(1, 10):
        for j in range(1, 10):
            val = i * j
            if val != X:
                total_sum += val

    print(total_sum)

if __name__ == '__main__':
    main()

import sys

def main():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Read N and D
    try:
        N = int(next(iterator))
        D = int(next(iterator))

        # Read snake data
        snakes = []
        for _ in range(N):
            t = int(next(iterator))
            l = int(next(iterator))
            snakes.append((t, l))

        # For each k from 1 to D
        for k in range(1, D + 1):
            max_weight = 0
            for t, l in snakes:
                # Weight is thickness * (length + k)
                weight = t * (l + k)
                if weight > max_weight:
                    max_weight = weight
            print(max_weight)

    except StopIteration:
        pass

if __name__ == '__main__':
    main()
